We say that a binary operation $f$ on $\mathbb L$ is \emph{perfectly dominated by the first argument on $A\times B$} if for all tuples $a\in A^3$ and $b\in B^3$ the following two implications hold: \begin{itemize}
    \item if $a_1|a_2a_3$, then $f(a_1,b_1)|f(a_2,b_2)f(a_3,b_3)$, and
    \item if $b_1|b_2 b_3$, then $f(a_1,b_1)|f(a_1,b_2)f(a_1,b_3)$.

For every finite set $U$ and its generic partition $(U_0,U_1)$, we may therefore assume $\ensuremath{\mathrm{tx}}\xspace$ to be perfectly dominated by the arguments of $U_0$ over $U_1$ and to satisfy \begin{equation}\label{phylo:eq:affine_tree}
   \ensuremath{\mathrm{tx}}\xspace(U_0\times U_0)\prec \ensuremath{\mathrm{tx}}\xspace(U_1\times U_1)\prec\ensuremath{\mathrm{tx}}\xspace(U_0\times U_1)\prec\ensuremath{\mathrm{tx}}\xspace(U_1\times U_0). 
\end{equation}

\begin{equation}\label{phylo:eq:affine_tree}
   \ensuremath{\mathrm{tx}}\xspace(U_0\times U_0)\prec \ensuremath{\mathrm{tx}}\xspace(U_1\times U_1)\prec\ensuremath{\mathrm{tx}}\xspace(U_0\times U_1)\prec\ensuremath{\mathrm{tx}}\xspace(U_1\times U_0). 
\end{equation}

\label{phylo:def:splits}
   Let $t$ be an $n$-tuple on $\mathbb L^k$. We say that $t$ is  
    \begin{itemize}
        \item \emph{uniformly split} 
        if it holds for for all $i,j\in \br n$  that $\mathrm{pr}_i(\ensuremath{\mathrm{s}}\xspace(t))=\mathrm{pr}_j(\ensuremath{\mathrm{s}}\xspace(t))$,
        \item \emph{evenly split} if it holds for for all $i,j\in \br n$ that $\ensuremath{\mathrm{s}}\xspace(t_i)=\ensuremath{\mathrm{s}}\xspace(t_j)$,
        \item \emph{partially constant split} if there is $i\in \br n$ such that $\mathrm{pr}_i(\ensuremath{\mathrm{s}}\xspace(t))\in\{0^k,1^k\}$,
        \item \emph{half-constant split} if $t$ is partially constant split and $n=2$, and
        \item a \emph{pseudo-loop} if it holds for for all $i,j\in \br n$ that $t_i\sim_kt_j$.
    \end{itemize}

\label{phylo:lemma:graph:even}
