    Then there is $\binom{e}{f}\in E$ such that $\ensuremath{\mathrm{s}}\xspace(e)=\ensuremath{\mathrm{s}}\xspace(f)$ and $\mathrm{pr}_{I_0(e)}(e)\sim \mathrm{pr}_{I_0(e)}(f)$.

\label{phylo:graph:lemma:right_side_split}
    Let $E$ be a binary relation on $\mathbb L^k$ that is preserved by $\gen{\ensuremath{\mathrm{tx}}\xspace}$. 
    Moreover, let $E$ be smooth. If there is $\binom{a}{b}\in E'$ such that $a$ and $b$ are aligned to the $m$-th degree for some $m\geq 1$, and $\mathrm{pr}_{I_{1^{m}}(a)}(a)|\mathrm{pr}_{I_{1^{m}}(a)}(b)$, then $E'$ contains a pseudo-loop.

\mo{
Without loss of generality, $\mathrm{pr}_{I_{1^{m}}(a)}(a)\prec\mathrm{pr}_{I_{1^{m}}(a)}(b)$. Denote the set of entries of $a$ by $U(a)$, and those of $b$ by $U(b)$.
Then $U(a)\cup U(b)\setminus U_{1^m}(b)\prec U_{1^m}(b).$}

By smoothness of $E'$, there is $c\in \mathbb L^k$ such that $\binom{c}{a}\in E'$. Denote the set of entries of $\binom{c}{a}$ by $V$.

Choose an automorphism $\alpha\in\mathrm{Aut}\Phylo$ such that
\begin{itemize}
    \item $U(a)\cup (U(b)\setminus U_{1^m}(b))\prec \alpha V\prec U_{1^m}(b)$, 

    \item $U_{1^{m-1}0}(b)| \alpha V$,
    \item $U_{1^{m-1}0}(b)\cup \alpha V|U_{1^{m}}(b)$,
\end{itemize}
and such that $\ensuremath{\mathrm{tx}}\xspace$ is dominated by $U_{1^{m-1}0}(b)$ over $\alpha V$ over $U_{1^{m}}(b)$.

\mo{Contrary to our usual assumption (\ref{phylo:eq:affine_tree}), we choose $\ensuremath{\mathrm{tx}}\xspace$ such that $\ensuremath{\mathrm{tx}}\xspace(\alpha V\times U_0(b))\prec\ldots\prec \ensuremath{\mathrm{tx}}\xspace(\alpha V\times U_{1^{m}}(b)).$}

Now $\binom{e}{f}\mathrel{\mathop:}\mathrel{\mkern-1.2mu}=\ensuremath{\mathrm{tx}}\xspace(\binom{a}{b},\alpha\binom{c}{a})$ satisfies $e\sim a$, and 
\begin{itemize}
    \item $I_{1^m}(f)=  I_{1^m}(a)$,
    \item \mo{$I_{1^{m-1}}(f)=  I_{1^{m-1}}(a),$}
    \item $\mathrm{pr}_{\br{k}\setminus I_{1^m}(f)}(f)\sim \mathrm{pr}_{\br{k}\setminus I_{1^m}(f)}(b)\sim \mathrm{pr}_{ I_{1^m}^c(f)}(a)$,  as well as
    \item $\mathrm{pr}_{ I_{1^m}(f)}(f)\sim \mathrm{pr}_{ I_{1^m}(a)}(a)$,
\end{itemize}













so in total $e\sim a\sim f$.

The proof is by induction on $k$. 

For $k=1$, every edge is a pseudo-loop. Now, suppose that the statement is true for all $\ell<k$. 

By \Cref{phylo:lemma:graph:even}, $E$ contains a half-constant split edge $\binom{a}{b}$ that is aligned to the $1$-st degree. Clearly, this edge can be chosen within $E'$. 

Denote the sets of entries of $a$ and $b$ by $U(a)$ and $U(b)$.

We run the following procedure. 

\begin{enumerate}
    \item\label{phylo:prop:graph:pL:case1} If $\mathrm{pr}_{I_{1}(a)}(a)|\mathrm{pr}_{I_{1}(a)}(b)$, \Cref{phylo:graph:lemma:right_side_split} yields a pseudo-loop.
    \item\label{phylo:prop:graph:pL:case2} If $\mathrm{pr}_{I_{1}(a)}(a)\mathrm{pr}_{I_{1}(a)}(b)|\mathrm{pr}_{I_{0}(a)}(b)$, we can, by the induction hypothesis, choose a pseudo-loop $\binom{\tilde{c}}{\tilde{d}}$ in  $\mathrm{pr}_{I_{1}(a)}(E)$, as well as $\binom{c}{d}\in\mathrm{pr}^{-1}_{I_{1}(a)}(\binom{\tilde{c}}{\tilde{d}}).$ Denote the set of entries of $c$ and $d$ by $U(c)$ and $U(d)$.
    We can choose an automorphism $\alpha\in\mathrm{Aut}\Phylo$ such that 
    \begin{itemize}
        \item $U_0(a)\cup U_0(b)\prec \alpha(U(c)\cup U(d))\prec U_1(a)\cup U_1(b)$,
        \item $U_0(a)\cup U_0(b)|\alpha(U(c)\cup U(d))\cup U_1(a)\cup U_1(b)$, and
        \item $\alpha(U(c)\cup U(d))|U_1(a)\cup U_1(b)$.
    \end{itemize}

    Consider $\binom{e}{f}\mathrel{\mathop:}\mathrel{\mkern-1.2mu}=\ensuremath{\mathrm{tx}}\xspace(\binom{a}{b},\binom{c}{d})\in E'$, and note that 
    \begin{itemize}
        \item $\ensuremath{\mathrm{s}}\xspace(e)=\ensuremath{\mathrm{s}}\xspace(f)=\ensuremath{\mathrm{s}}\xspace(a)$,
        \item $\mathrm{pr}_{I_{0}(a)}(e)\sim \mathrm{pr}_{I_{0}(a)}(a)\sim \mathrm{pr}_{I_{0}(a)}(b)\sim \mathrm{pr}_{I_{0}(a)}(f)$, and 
        \item $\mathrm{pr}_{I_{1}(a)}(e)\sim \tilde{c}\sim \tilde{d}\sim \mathrm{pr}_{I_{1}(a)}(f)$. 
    \end{itemize}
    In other words, $\binom{e}{f}$ is a pseudo-loop.

    \item\label{phylo:prop:graph:pL:case3} Otherwise, we know that some of the entries of  $\mathrm{pr}_{I_{1}(a)}(a)$ are closer to $U_0(b)$, and some are closer to $U_1(b)$, i.e., $U_{10}(a)\cup U_0(b)|U_{1^2}(a)\cup U_1(b)$.

    By smoothness of $E'$, there is $c\in \mathbb L^k$ such that $\binom{c}{a}\in E'$.

    The homogeneity of $\Phylo$ now allows us to choose an automorphism $\alpha\in\mathrm{Aut}(\Phylo))$ such that, denoting the set of entries of $\binom{c}{a}$ by $V$, 
    $U_{10}(a)\cup U_{0}(b)\prec \alpha V\prec U_{1^2}(a)\cup U_{1}(b)$,
    $U_{10}(a)\cup U_{0}(b)| \alpha V$, and 
    $\alpha V|U_{1^2}(a)\cup U_{1}(b)$.
    The affine tree operation $\ensuremath{\mathrm{tx}}\xspace$ can now be chosen to be perfectly dominated by $U_{10}(a)\cup U_{0}(b)$ over $ \alpha V$ over $U_{1^{2}}(a)\cup U_{1}(b)$.
    Similarly to the proof of \Cref{phylo:graph:lemma:right_side_split}, we require that, opposed to our usual assumption (\ref{phylo:eq:affine_tree}), $\ensuremath{\mathrm{tx}}\xspace$ satisfies
\begin{equation}\label{phylo:prop:graph:pL:eq1}
    \ensuremath{\mathrm{tx}}\xspace(U_0(a)\times\alpha V)\prec \ensuremath{\mathrm{tx}}\xspace(U_{10}(a)\times\alpha V)\prec \ensuremath{\mathrm{tx}}\xspace(U_{1^2}(a)\times\alpha V),
\end{equation}

and the same for $b$ in place of $a$.
As a result, we get
\begin{align}
    \mathrm{pr}_{I_{1^{2}}^c(a)}(\ensuremath{\mathrm{tx}}\xspace(a,\alpha c))&\sim\mathrm{pr}_{I_{1^{2}}^c(a)}(a),\label{phylo:prop:graph:pL:eq2_1}
    \intertext{due to the perfect domination of $\ensuremath{\mathrm{tx}}\xspace$, and for the same reason also}
    \mathrm{pr}_{I_{1^{}}^c(a)}(\ensuremath{\mathrm{tx}}\xspace(b,\alpha a))&\sim\mathrm{pr}_{I_{1^{}}^c(a)}(b)\sim \mathrm{pr}_{I_{1^{}}^c(a)}(a),
    \intertext{and}
    \mathrm{pr}_{I_{1^{}}(a)}(\ensuremath{\mathrm{tx}}\xspace(b,\alpha a))&\sim\mathrm{pr}_{I_{1^{}}(a)}(a).
    \intertext{
    Further, by $\ensuremath{\mathrm{tx}}\xspace$ being an affine tree operation and 
    assumption (\ref{phylo:prop:graph:pL:eq1}), it follows that}
    I_{w}(a) =I_{w}(\ensuremath{\mathrm{tx}}\xspace(a,\alpha c))&= I_{w}(\ensuremath{\mathrm{tx}}\xspace(b,\alpha a))\label{phylo:prop:graph:pL:eq2_4}
    \intertext{for all words $w\in\{0,1,1^2\}$. 

