\label{phylo:lemma:hyp:parity}
    Let $\ensuremath{R}\xspace$ be an $n$-ary relation on $\mathbb L^k$ that is preserved by $\gen{\ensuremath{\mathrm{tx}}\xspace}$.

    If $\ensuremath{R}\xspace$ is cyclic, then either $\ensuremath{R}\xspace$ contains a uniformly split tuple, or it holds for all $t\in \ensuremath{R}\xspace$ that $\sum_{1\leq i\leq n}\mathrm{pr}_i(\ensuremath{\mathrm{s}}\xspace(t))\in\{\overline 0,\overline 1\}$.

\label{phylo:lemma:hyp:symmetric}
    Let $\ensuremath{R}\xspace$ be an $n$-ary relation on $\mathbb L^k$ that is preserved by $\gen{\ensuremath{\mathrm{tx}}\xspace}$.

    If $\ensuremath{R}\xspace$ is symmetric, then $\ensuremath{R}\xspace$ contains tuple $t'$ that is either uniformly split, or $n-1$ of its vertices are split uniformly, while one splits dually or constant with respect to the uniform partition.

\label{lemma:min:minclean}
    Let $E$ be a binary relation on $\mathbb{Q}^k$ that is preserved by $\min$.
    If $E$ is smooth, then  $E$ contains a min-clean tuple.

\label{l:mx:fencing}
Let $E$ be a binary relation on $\mathbb{Q}^k$ that is preserved by $\gen{\mathrm{mx}}$. Either $E$ contains a tuple $t$ with $|M(t)|=1$, or  
for all $t, t'\in E$ with $\min(t_i)=\min(t'_i)$ and $\mathrm{minx}(t_i)=\mathrm{minx}(t'_i)$ for $i \in \{1,2\}$, also  $\mathrm{minx}(t_j)=\mathrm{minx}(t'_j)$ for $j \neq i$.

\label{lemma:lex:minx_int2}
Let $S$ be a binary relation on $\mathbb{Q}^k$. If $S$ is smooth, weakly connected, and of pseudo-algebraic length $1$, then either $\genrel{S}{\mathrm{lex}}$ contains a tuple $t$ with $|M(t)|=1$, or  
     $\bigcap_{a\in \mathrm{supp}(S)}\mathrm{minx}(a)\neq\varnothing$.
